        return ""
    if IS_MACOS:
        return f"{disk_path}s{index}"
    # Linux: nvme0n1 -> nvme0n1p3, sdb -> sdb3 (isim rakamla bitiyorsa 'p')
    taban = disk_path.rstrip("/")
    ek = "p" if taban[-1:].isdigit() else ""
